package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
public class MediaShelfTest {
 private MediaShelf.Item item(MediaShelf s,String type,String name,long at){return s.touch(type,"content://media/"+name,name,at,type.equals("pdf")?10:600000,100);}
 @Test public void mixedCollectionAndAnchoredNotesRoundTrip(){MediaShelf s=new MediaShelf();MediaShelf.Item audio=item(s,"audio","a",12000),video=item(s,"video","v",6000),pdf=item(s,"pdf","p",2);MediaShelf.Collection c=s.create("Curso");assertTrue(s.add(c.id,audio.id));assertTrue(s.add(c.id,video.id));assertTrue(s.add(c.id,pdf.id));assertTrue(s.note(pdf.id,"",2,"Revisar\namanhã"));MediaShelf copy=MediaShelf.decode(s.encode());assertTrue(copy.valid);assertEquals(3,copy.collections.get(c.id).items.size());assertEquals(2,copy.items.get(pdf.id).notes.get(0).at);assertEquals("Revisar\namanhã",copy.items.get(pdf.id).notes.get(0).text);}
 @Test public void progressUpdatesKeepNamesCollectionsAndNotes(){MediaShelf s=new MediaShelf();MediaShelf.Item i=item(s,"video","Aula",5000);MediaShelf.Collection c=s.create("Estudo");s.add(c.id,i.id);s.note(i.id,"",5000,"Anotação");s.touch("video",i.uri,"",19000,600000,200);assertEquals(1,s.items.size());assertEquals("Aula",i.title);assertEquals(19000,i.position);assertEquals(5000,i.notes.get(0).at);assertTrue(s.pinned(i.id));}
 @Test public void onlyUnpinnedUnannotatedEntriesCanBeEvicted(){MediaShelf s=new MediaShelf();MediaShelf.Item protectedItem=item(s,"audio","keep",10);s.note(protectedItem.id,"",10,"Guarde");for(int i=0;i<250;i++)item(s,"audio","other"+i,1000);assertEquals(MediaShelf.ITEMS,s.items.size());assertNotNull(s.items.get(protectedItem.id));}
 @Test public void fullProtectedSpaceRefusesNewFilesWithoutDroppingData(){MediaShelf s=new MediaShelf();for(int i=0;i<MediaShelf.ITEMS;i++){MediaShelf.Item entry=item(s,"pdf","p"+i,0);s.note(entry.id,"",0,"Guarde");}assertNull(item(s,"pdf","overflow",0));assertEquals(MediaShelf.ITEMS,s.items.size());}
 @Test public void boundsAndDeduplicationAreEnforced(){MediaShelf s=new MediaShelf();MediaShelf.Collection c=s.create("Coleção");for(int i=0;i<51;i++){MediaShelf.Item entry=item(s,"video","v"+i,1000);assertEquals(i<50,s.add(c.id,entry.id));}assertTrue(s.add(c.id,c.items.get(0)));MediaShelf.Item entry=s.items.get(c.items.get(0));for(int i=0;i<10;i++)assertTrue(s.note(entry.id,"",1000,"Nota "+i));assertFalse(s.note(entry.id,"",1000,"Extra"));assertFalse(s.note(entry.id,"",-1,"Inválida"));assertNull(s.touch("audio","https://example.com/private?token=x","Online",0,0,0));}
 @Test public void malformedAndFutureDataAreReadOnly(){for(String raw:new String[]{"broken","{\"v\":2}","{\"items\":[{\"id\":\"x\",\"type\":\"pdf\",\"uri\":\"https://example.org\"}]}"}){MediaShelf s=MediaShelf.decode(raw);assertFalse(s.valid);assertNull(s.create("Cannot overwrite"));}}
 @Test public void editedNoteKeepsItsAnchorAndCollectionDeletionKeepsFiles(){MediaShelf s=new MediaShelf();MediaShelf.Item i=item(s,"audio","music",30000);s.note(i.id,"",12000,"Original");String id=i.notes.get(0).id;assertTrue(s.note(i.id,id,30000,"Editada"));assertEquals(12000,i.notes.get(0).at);MediaShelf.Collection c=s.create("Coleção");s.add(c.id,i.id);s.collections.remove(c.id);assertNotNull(s.items.get(i.id));assertEquals("Editada",i.notes.get(0).text);}
 @Test public void pagesAndFinishedMediaAreClamped(){MediaShelf s=new MediaShelf();MediaShelf.Item p=item(s,"pdf","p",99);assertEquals(9,p.position);MediaShelf.Item a=item(s,"audio","a",600000);assertEquals(0,a.position);assertFalse(s.note(p.id,"",10,"Fora"));}
 @Test public void removingLastCollectionReferenceRevealsHiddenAnnotations(){MediaShelf s=new MediaShelf();MediaShelf.Item i=item(s,"pdf","p",1);s.note(i.id,"",1,"Keep");MediaShelf.Collection a=s.create("A"),b=s.create("B");s.add(a.id,i.id);s.add(b.id,i.id);assertTrue(s.hide(i.id));assertTrue(s.removeFrom(a.id,i.id,200));assertEquals(0,i.seen);assertTrue(s.removeCollection(b.id,300));assertEquals(300,i.seen);assertFalse(s.hide(i.id));assertEquals("Keep",i.notes.get(0).text);}
}
